    each_way("cycles", |run, how| {
        for component in ["OutsideFirst", "InsideFirst"] {
            for (prop, want) in &expected {
                assert_eq!(&prop_type(&run.outcome, component, prop), want, "{how}: {component}.{prop}");
            }
        }
    });
}

