                let target = self.rpc.target_of_type(info.id).await?;
                match BasesOf::of(&target) {
                    BasesOf::Itself => Ok(Some(self.rpc.base_types(target.id).await?)),
                    _ => Ok(info.is_tuple_type.then(Vec::new)),
                }
            }
            BasesOf::None => Ok(Some(Vec::new())),
